mapper.select:
SELECT
,ui.id as info_id,ui.first_name,ui.last_name FROM gc_video_comment AS vc LEFT JOIN gc_user AS u ON u.id=vc.user_id LEFT JOIN gc_user_info ui on ui.id=u.info_id LEFT JOIN sys_file f on ui.avatar_file_id=f.id LEFT JOIN sys_file cf on vc.file_id=cf.id WHERE vc.video_id=#{vid} ORDER BY create_time DESC
limit #{limit}
